from dataclasses import dataclass
from typing import List


@dataclass(frozen=True)
class DecisionData:
    """Represents a security decision generated by VoltGuard."""

    decision_id: str
    timestamp: str
    title: str
    decision: str
    severity: str
    confidence: int
    asset: str
    source: str
    category: str
    reason: str
    recommended_action: str


