    def get_risk_score(
        self,
        decisions: List[DecisionData],
    ) -> int:
        """Calculate a simple dashboard risk score."""

        if not decisions:
            return 0

        weights = {
            "CRITICAL": 100,
            "HIGH": 75,
            "MEDIUM": 45,
            "LOW": 20,
        }

        total = sum(
            weights.get(
                decision.severity,
                0,
            )
            for decision in decisions
        )

        maximum = len(decisions) * 100

        score = int(
            (total / maximum) * 100
        )

        return min(
            max(score, 0),
            100,
        )